import apps.core.platform
from django.db import migrations, models
from django.utils import timezone

from apps.core.platform import MIN_CONTRAST
from apps.schools.colors import contrast

# Couleurs par défaut d'avant la marque (lot 1) et leurs remplaçantes : bleu uniforme, soleil levant.
PRIMARY = ("#0B5FCC", "#1A2F80")
ACCENT = ("#F2B632", "#FFA81E")


def recolour(apps, schema_editor):
    """Une couleur restée à l'ancien défaut prend la nouvelle ; une couleur choisie dans la console
    reste. Si le mélange devenait illisible (soleil sur une couleur principale choisie), on ne
    change rien. `updated_at` change : les images de partage se redessinent."""
    for platform in apps.get_model("core", "PlatformSettings").objects.all():
        primary = PRIMARY[1] if platform.primary_color == PRIMARY[0] else platform.primary_color
        accent = ACCENT[1] if platform.accent_color == ACCENT[0] else platform.accent_color
        changed = (primary, accent) != (platform.primary_color, platform.accent_color)
        if changed and contrast(primary, accent) >= MIN_CONTRAST:
            platform.primary_color, platform.accent_color = primary, accent
            platform.updated_at = timezone.now()
            platform.save(update_fields=["primary_color", "accent_color", "updated_at"])



